 "content": "def transform(grid):
    """Replicate the non-background colored motif wherever its footprint is all zero."""
    h, w = len(grid), len(grid[0])
    colors = {v for row in grid for v in row if v not in (0, 3)}
    if len(colors) != 1:
        # Generalize the background as the most frequent non-marker value.
        colors = {v for row in grid for v in row if v not in (0,)}
        color = max(colors, key=lambda v: sum(row.count(v) for row in grid))
    else:
        color = next(iter(colors))
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
    if not pts:
        return [row[:] for row in grid]
    r0, c0 = min(r for r, c in pts), min(c for r, c in pts)
    shape = [(r-r0, c-c0) for r, c in pts]
    sh, sw = max(r for r, c in shape)+1, max(c for r, c in shape)+1
    out = [row[:] for row in grid]
    for ar in range(h-sh+1):
        for ac in range(w-sw+1):
            if all(grid[ar+dr][ac+dc] == 0 for dr, dc in shape):
                for dr, dc in shape:
                    out[ar+dr][ac+dc] = color
    return out
